from pathlib import Path
q='Map_with_BWA_MEM_on_dataset_1_and_2__mapped_reads_in_BAM_format_.bam'
rows=[]
n=0
with Path('/workspace/gtcheck.tsv').open() as f:
    for line in f:
        if line.startswith('#'):
            continue
        if line.startswith('INFO'):
            continue
        if line.startswith('DCv2\\t[2]'):
            continue
        parts=line.rstrip('\\n').split('\\t')
        if len(parts)<7 or not parts[0].startswith('DCv2'):
            continue
        n+=1
        if parts[1]==q or parts[2]==q:
            try:
                disc=float(parts[3]); sites=float(parts[5]); match=float(parts[6]); hwe=float(parts[4])
            except Exception as e:
                continue
            rows.append((disc/sites, disc, sites, match, hwe, parts[1], parts[2]))
print('total data rows',n,'query rows',len(rows))
rows.sort(key=lambda x:x[0])
for r in rows[:40]:
    print(f'{r[0]:.8f}\\tdisc={r[1]:.1f}\\tsites={r[2]:.0f}\\tmatch={r[3]:.0f}\\thwe={r[4]:.4f}\\t{r[5]}\\t{r[6]}')
print('col2 q', sum(1 for r in rows if r[5]==q), 'col3 q', sum(1 for r in rows if r[6]==q))
PY"

